      ro: ["Lacul Skadar", "Rezistență istorică", "Ruine", "Simbolistică"],
      en: ["Lake Skadar", "Historical resistance", "Ruins", "Symbolism"],
      es: ["Lago Skadar", "Resistencia histórica", "Ruinas", "Simbolismo"],
